const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
function page(options={}){let p,identity=1,purchased=false,calls=0;const offer={id:'26',price:688,feeText:'￥688.00',available:true,courses:[{id:'7',title:'奖励的误区'}]};const auth={isLoggedIn:()=>options.loggedIn!==false,requireLogin:()=>options.loggedIn!==false};const service={call:async()=>({offer,purchased}),error:(p,e)=>p.setData({error:e.message})};const payment={enroll:async(payload,fee,opts)=>{calls++;assert.deepEqual(JSON.parse(JSON.stringify(payload)),{});assert.equal(fee,'￥688.00');assert.equal(opts.action,'education-bundle-pay');if(options.pay)return options.pay(()=>identity++,()=>purchased=true);purchased=true;return {enrollment:{id:1}};}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../../pages/education-bundle/education-bundle.js'),'utf8'),{Page:x=>p=x,require:n=>n.endsWith('/auth')?auth:n.endsWith('/consultationService')?service:n.endsWith('/coursePayment')?payment:{capture:()=>identity,current:x=>x===identity},wx:{showToast(){},setClipboardData(){}}});p.data=structuredClone(p.data);p.setData=values=>Object.assign(p.data,values);return{p,calls:()=>calls};}
test('课程包游客可查看价格和目录，购买先要求登录',async()=>{const h=page({loggedIn:false});await h.p.refresh();assert.equal(h.p.data.offer.price,688);await h.p.buy();assert.equal(h.calls(),0);assert.equal(h.p.data.purchased,false);});
test('课程包付款后重新读后台权益，避免客户端回调直接开通',async()=>{const h=page({pay:async()=>({enrollment:{id:1}})});await h.p.refresh();await h.p.buy();assert.equal(h.calls(),1);assert.equal(h.p.data.purchased,false);assert.equal(h.p.data.busy,false);});
test('支付成功且后台确认后展示已购买，已购不能重复下单',async()=>{const h=page();await h.p.refresh();await h.p.buy();assert.equal(h.p.data.purchased,true);await h.p.buy();assert.equal(h.calls(),1);});
test('微信登录后无需填写姓名或手机，支付失败提示查询原订单',async()=>{const h=page({pay:async()=>{throw Error('支付结果正在确认，请稍后刷新');}});await h.p.refresh();assert.equal(h.p.data.form,undefined);await h.p.buy();assert.equal(h.calls(),1);assert.match(h.p.data.error,/刷新/);assert.equal(h.p.data.purchased,false);assert.equal(h.p.data.busy,false);});
test('身份切换后的旧支付回调不能更新新账号权益',async()=>{const h=page({pay:async(change,bought)=>{change();bought();return{enrollment:{id:1}};}});await h.p.refresh();await h.p.buy();assert.equal(h.p.data.purchased,false);});
